INSERT INTO `sys_config` VALUES (4, '账号自助-验证码开关', 'sys.account.captchaEnabled', 'true', 'Y', 'admin', '2026-03-26 15:07:13', '', NULL, '是否开启验证码功能（true开启，false关闭）');
